function RootMotionCustoms:__init( rootMotion_, moveScales_walk_, moveScales_run_, isMovingFunc_ )

    self.rootMotion = rootMotion_
    self.moveScales = {}
    self.moveScales.walk = moveScales_walk_
    self.moveScales.run = moveScales_run_

    assert( type(isMovingFunc_) == "function" )
    self.isMovingFunc = isMovingFunc_


    self.DonAnimatorMoveFunc = Bind( self, self.DonAnimatorMove )

    if self:IsNeedBindOnAnimatorMove()  then 
        self.rootMotion:OnAnimatorMoveFunc( '+', self.DonAnimatorMoveFunc )
    end 

end


function RootMotionCustoms:__delete()
    if self:IsNeedBindOnAnimatorMove()  then 
        self.rootMotion:OnAnimatorMoveFunc( '-', self.DonAnimatorMoveFunc )
    end 
end



function RootMotionCustoms:IsNeedBindOnAnimatorMove()
    return isNotNull(self.rootMotion.OnAnimatorMoveFunc) and 
        (not Mathf.Approximately(self.moveScales.walk, 1.0)) and 
        (not Mathf.Approximately(self.moveScales.run, 1.0))
end



function RootMotionCustoms:DonAnimatorMove()

    local MoveMagnitude = InputManager.GetCachedMoveMagnitude()

    local s = Mathf.Clamp01( KTool.Remap( 0.4, 0.7, 0, 1, MoveMagnitude ) )
    s = KTool.Remap( 0, 1, self.moveScales.walk, self.moveScales.run, s )
    --print("新 rootMotion scale: " .. tostring(s))

    local moveScale = 1.0
    if self.isMovingFunc() == true then
        moveScale = s
    end

    ------
    local rm = self.rootMotion
    local y = rm.animator.deltaPosition.y 
    local deltaPos = rm.animator.deltaPosition * moveScale
    deltaPos.y = y

    rm.positionDelta = rm.positionDelta + deltaPos
    rm.rotationDelta = rm.animator.deltaRotation * rm.rotationDelta
end





return RootMotionCustoms